std::shared_ptr<GpuTexture> GpuMaterialComposer::Overlay(const GpuTexture& source,const OverlayDefinition& overlay,int width,int height){if(!overlay.Texture)throw std::runtime_error("Overlay has no image payload.");auto texture=Embedded(*overlay.Texture);return Compose(source,*ShaderMaterial("overlay.composite"),width,height,{{"_Overlay",texture.get()}},true);}
std::shared_ptr<GpuTexture> GpuMaterialComposer::Copy(const GpuTexture& source,int width,int height){auto result=std::make_shared<GpuTexture>(graphics_,width,height,true,DXGI_FORMAT_B8G8R8A8_UNORM_SRGB,true,D3D11_FILTER_MIN_MAG_LINEAR_MIP_POINT,EffectiveAnisotropy(1,anisotropicFiltering_));Copier().Copy(source,*result);result->GenerateMips(graphics_);return result;}
