std::shared_ptr<GpuTexture> GpuMaterialComposer::ResolveTexture(const GpuMaterialInstance& material,const std::string& property){auto override=material.TextureOverrides.find(property);if(override!=material.TextureOverrides.end())return override->second;auto loose=material.ImageSelections.find(property);if(loose!=material.ImageSelections.end())return LooseImage(loose->second);auto binding=material.Textures.find(property);if(binding!=material.Textures.end()&&binding->second.Texture.PathId){auto type=store_.AssetClass(binding->second.Texture);if(type==28||type==89)return Texture(binding->second.Texture);SourceReferenceDiagnostics.insert("Dangling authored texture: "+material.Name+"/"+property+": "+Key(binding->second.Texture));}auto fallback=material.DefaultTextures.find(property);return Default(fallback==material.DefaultTextures.end()?"white":fallback->second);}
