std::shared_ptr<GpuTexture> GpuMaterialComposer::Default(const std::string& name){auto found=defaults_.find(name);if(found!=defaults_.end())return found->second;std::vector<std::uint8_t>rgba;if(name.empty()||name=="white")rgba={255,255,255,255};else if(name=="black")rgba={0,0,0,0};else if(name=="opaque-black")rgba={0,0,0,255};else if(name=="gray"||name=="grey")rgba={127,127,127,127};else if(name=="red")rgba={255,0,0,0};else if(name=="bump")rgba={127,127,255,255};else throw std::runtime_error("Unknown default texture: "+name);GpuTextureData data;data.Name=name;data.Width=data.Height=1;data.Format=4;data.Srgb=name=="gray"||name=="grey";data.Bytes=std::move(rgba);auto texture=std::make_shared<GpuTexture>(graphics_,data);defaults_[name]=texture;return texture;}
std::vector<std::uint8_t> GpuMaterialComposer::ReadImage(const GpuTexture& texture){D3D11_TEXTURE2D_DESC description{};texture.Texture->GetDesc(&description);std::vector<std::uint8_t> pixels;if(description.Format==DXGI_FORMAT_B8G8R8A8_UNORM||description.Format==DXGI_FORMAT_B8G8R8A8_UNORM_SRGB||description.Format==DXGI_FORMAT_B8G8R8A8_TYPELESS)pixels=graphics_.Readback(texture.Texture.Get());else{GpuTexture resolved(graphics_,texture.Width(),texture.Height(),true,DXGI_FORMAT_B8G8R8A8_UNORM_SRGB,false);Copier().Copy(texture,resolved);pixels=graphics_.Readback(resolved.Texture.Get());}const size_t stride=static_cast<size_t>(texture.Width())*4;std::vector<std::uint8_t>top(pixels.size());for(int row=0;row<texture.Height();++row)std::memcpy(top.data()+row*stride,pixels.data()+(texture.Height()-1-row)*stride,stride);return top;}
float GpuMaterialComposer::Linear(float value){return value<=.04045f?value/12.92f:value<1?std::pow((value+.055f)/1.055f,2.4f):std::pow(value,2.2f);}
